 function refresh(){if(!ui.ready)return;markAssisted();const h=tableView.presented||state.hand,replay=ui.route==='review'&&state.review?state.reviewFrames[state.reviewIndex]:null,c=replay?state.review.config:state.config,you=replay?state.review.hero:state.hero;if(c){const r0=liveSession.rootConfig,root=!replay&&!state.dirty&&r0?.variant===c.variant&&r0.mode===c.mode&&r0.seats>=c.seats?r0:null,g=root||c,gy=root?liveSession.rootHero:you;$('uiGameSummary').textContent=(replay?'Replay · ':'')+g.variant+' · '+(g.mode==='cash'?'Cash':'Tournament')+' · '+g.seats+' seats · '+fmt(g.stacks[gy]??g.stacks[0])+' bb';$('uiPaneSummary').textContent=$('uiGameSummary').textContent;$('uiGameContext').textContent=replay?G.STREET[replay.street]+' · '+(replay.done?'Hand complete':reviewSeatName(replay.actor)+' to act'):(state.dirty?'Setup changes not applied · ':'')+(h?G.STREET[h.street]+' · '+(h.done?'Hand complete':G.positions(h.n,h.button)[h.actor]+' to act'):'');}
  document.body.dataset.format=$('mode').value;document.body.dataset.playSeats=String(h?.n||0);$('uiNotices').textContent=$('status').classList.contains('error')?$('status').textContent:'';
  if(h){$('uiHandLine').textContent=compactLine(h);const names=seatNames(h,state.hero);$('handLog').innerHTML=[...historyLog(h.log).map(e=>eventLabel(e,names)),...showdownLines(h,names),...handResultLines(h,names)].map(line=>'<div>'+esc(line)+'</div>').join('');renderPaneHands();
   $('uiCustomBet').hidden=$('customBet').classList.contains('hide');$('uiShowHistory').disabled=false;
   const same=!h.done&&ui.feedbackKey===PokerSpot.publicKey(observedData(h)),assessing=state.job==='spotSolve'&&!!state.pending?.background,solving=!assessing&&state.job==='spotSolve'&&!['quiz','quizPrepare','review'].includes(state.pending?.kind);$('uiResultDetails').hidden=!(solving||assessing||ui.feedbackKey&&same&&ui.feedbackSupported!==false)||!!$('currentPolicy').querySelector('.guess-lock');$('uiResultDetails').querySelector('summary').textContent=assessing?'Assessing your previous action…':solving?'Solving this position…':same?'Action values':'Previous decision details';if(solving)$('uiResultDetails').open=true;
   const result=h.done?null:activeSpotResult(h);
   if(!result&&$('currentPolicy').textContent.includes('Ready to solve this position'))$('currentPolicy').querySelector('.notice')?.classList.replace('notice','ui-ready-hint');
  }
  $('spotStop').hidden=state.job!=='spotSolve';$('uiSavedEmpty').hidden=!!transferUI.drill;$('uiGameBusy').hidden=!state.busy;
  $('uiTopicSummary').textContent=[$('quizVariant').selectedOptions[0]?.textContent,$('quizFormat').selectedOptions[0]?.textContent,$('quizTopic').selectedOptions[0]?.textContent].filter(Boolean).join(' · ');
  const qh=state.quiz?.hand;document.body.dataset.practiceActive=String(ui.route==='quiz'&&!!qh&&!state.quiz.completedHand);document.body.dataset.practiceSeats=String(qh?.n||0);$('uiQuizLine').textContent=qh?compactLine(qh):'';quizHistory.hidden=!qh;$('uiQuizLine').parentElement.hidden=!qh;
  $('uiQuizHistoryButton').setAttribute('aria-expanded',String(quizHistory.open));$('uiTopicsButton').setAttribute('aria-expanded',String(practiceTopics.open));
 }
 const observer=new MutationObserver(refresh);for(const id of ['status','quizSpot','quizStatus','quizHistory'])observer.observe($(id),{childList:true,subtree:true,characterData:true});
 document.querySelectorAll('.quiz-filter').forEach(el=>el.addEventListener('change',refresh));$('quizMix').addEventListener('click',refresh);practiceTopics.addEventListener('toggle',refresh);quizHistory.addEventListener('toggle',refresh);
